INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Verteilung von Aufgaben Teil der Durchführung?', 2, '[{"text": "Ja", "correct": true, "because": "Setzt Plan in Aktion"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Durchführung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat die Verteilung von Aufgaben?', 3, '[{"text": "Klare Zuständigkeiten schaffen", "correct": true, "because": "Fördert Effizienz"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}, {"text": "Neue Ziele definieren", "correct": false, "because": "Initiierungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aufgabenverteilung folgt dem PSP. b) Sie erfolgt nur in der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Durchführung entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Aufgabenverteilung?', 4, '[{"text": "Kompetenzen im Team", "correct": true, "because": "Bestimmen Zuweisung"}, {"text": "Unklare Rollen", "correct": false, "because": "Erschweren Verteilung"}, {"text": "Arbeitspakete", "correct": true, "because": "Definieren Aufgaben"}, {"text": "Zeitliche Verfügbarkeit", "correct": true, "because": "Beeinflusst Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Aufgabenverteilung effektiv durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Zuständigkeiten fehlen"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Aufgabenverteilung?', 3, '[{"text": "Projektmanagement-Tool", "correct": true, "because": "Weist Aufgaben zu"}, {"text": "Keine Kommunikation", "correct": false, "because": "Fehlt Klarheit"}, {"text": "Zufällige Liste", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Aufgabenverteilung nur für große Teams relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Aufgabenverteilung?', 3, '[{"text": "Effizienz durch klare Rollen", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Technische Lösung finden", "correct": false, "because": "Anderer Fokus"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aufgabenverteilung basiert auf dem Zeitplan. b) Sie ist immer konfliktfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Konflikte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Aufgabenverteilung?', 3, '[{"text": "Doppelarbeit entsteht", "correct": true, "because": "Keine Abstimmung"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Aufgabenverteilung ohne PSP erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur fehlt"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine gute Aufgabenverteilung?', 3, '[{"text": "Anna testet Modul 1 bis 15. Juni", "correct": true, "because": "Klar und konkret"}, {"text": "Jemand macht irgendwas", "correct": false, "because": "Zu vage"}, {"text": "Team soll arbeiten", "correct": false, "because": "Keine Zuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Aufgabenverteilung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Klarheit"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Aufgabenverteilung wichtig?', 4, '[{"text": "Kompetenzen", "correct": true, "because": "Passen Aufgaben zu Fähigkeiten"}, {"text": "Unklare Anweisungen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Zeitrahmen", "correct": true, "because": "Definiert Dauer"}, {"text": "Ressourcen", "correct": true, "because": "Beeinflussen Verfügbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Aufgabenverteilung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft bei der Aufgabenverteilung?', 3, '[{"text": "RACI-Matrix", "correct": true, "because": "Definiert Rollen"}, {"text": "Keine Abstimmung", "correct": false, "because": "Fehlt Struktur"}, {"text": "Spontane Zuweisung", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Aufgabenverteilung ohne Kommunikation erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Abstimmung nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Aufgabenverteilung?', 3, '[{"text": "Fehlende Kompetenzen", "correct": true, "because": "Verhindern Zuweisung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Verteilung"}, {"text": "Definierte Rollen", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aufgabenverteilung fördert Zusammenarbeit. b) Sie ist nur für IT-Aufgaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Aufgabenverteilung?', 3, '[{"text": "Optimale Ressourcennutzung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Koordination", "correct": false, "because": "Fördert Abstimmung"}]');